#!/usr/bin/env bash
# Checks that the app templates stay in step with the workspace:
# - the starter Rust crate (templates/app-rust) pins the same UniFFI version as
#   the workspace, so its bindings are generated by the same uniffi-bindgen;
# - every Android host ships the Kotlin half of rustls-platform-verifier at the
#   version the Rust half expects;
# - the native services' Swift adapters match the Rust interface version.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
status=0

workspace_uniffi="$(awk '/^name = "uniffi"$/ { getline; gsub(/version = |"/, ""); print; exit }' "$ROOT/Cargo.lock")"
if ! grep -qE "^uniffi = (\{ version = )?\"=${workspace_uniffi}\"" "$ROOT/templates/app-rust/Cargo.toml"; then
  echo "error: templates/app-rust/Cargo.toml must pin uniffi = \"=${workspace_uniffi}\" (the workspace's version)" >&2
  status=1
fi

# The Android hosts' Kotlin half of rustls-platform-verifier must be the exact
# version the Rust half expects (rustls-platform-verifier-android in Cargo.lock),
# or certificate checks fail at runtime with a JNI error.
lock_version="$(awk '/^name = "rustls-platform-verifier-android"$/ { getline; gsub(/version = |"/, ""); print; exit }' "$ROOT/Cargo.lock")"
if [[ -z "$lock_version" ]]; then
  echo "error: rustls-platform-verifier-android not found in Cargo.lock" >&2
  status=1
fi
for gradle in "$ROOT"/examples/*-android/app/build.gradle.kts "$ROOT"/templates/android-app/app/build.gradle.kts; do
  if ! grep -q "\"org.rustls:rustls-platform-verifier:${lock_version}\"" "$gradle"; then
    echo "error: ${gradle#"$ROOT/"} must depend on org.rustls:rustls-platform-verifier:${lock_version} (the version in Cargo.lock)" >&2
    status=1
  fi
done

# The native services' Swift adapters implement the interface version the
# Rust macro declares; a mismatch makes ForgeServices.install() refuse.
rust_services="$(sed -n 's/^pub const VERSION: u32 = \([0-9]*\);$/\1/p' "$ROOT/crates/forge-services/src/lib.rs")"
swift_services="$(sed -n 's/^let forgeServicesSwiftVersion: UInt32 = \([0-9]*\)$/\1/p' "$ROOT/crates/forge-services/swift/ForgeServices.swift")"
if [[ -z "$rust_services" || "$rust_services" != "$swift_services" ]]; then
  echo "error: forge-services VERSION (${rust_services:-missing}) and forgeServicesSwiftVersion (${swift_services:-missing}) differ" >&2
  status=1
fi

template_test="$ROOT/templates/ios-app/Tests/AppHostTests/NativeServicesTests.swift"
if ! grep -q "XCTAssertEqual(nativeServicesVersion(), ${rust_services})" "$template_test"; then
  echo "error: ${template_test#"$ROOT/"} must expect native services interface v${rust_services}" >&2
  status=1
fi

if [[ $status -eq 0 ]]; then
  echo "[forge] Starter crate uses uniffi ${workspace_uniffi}, like the workspace."
  echo "[forge] Android hosts use rustls-platform-verifier ${lock_version}, matching Cargo.lock."
  echo "[forge] Native services interface v${rust_services} in Rust and Swift."
fi
exit $status
